predicate sorted_seg<T(==)>(a: array<T>, low: int, high: int)
  reads a
  requires a != null && 0 <= low <= high <= a.Length
{
  forall i, j :: low <= i < j < high ==> a[i] <= a[j]
}

predicate unchanged<T(==)>(a: array<T>, b: array<T>, low: int, high: int)
  reads a, b
  requires a != null && b != null && a.Length == b.Length
  requires 0 <= low <= high <= a.Length
{
  forall i :: 0 <= i < a.Length && !(low <= i < high) ==> a[i] == b[i]
}

method selSort<T(==)>(a: array<T>, low: int, high: int) returns (b: array<T>)
  requires a != null
  requires 0 <= low <= high <= a.Length
  ensures b != null && b.Length == a.Length
  ensures sorted_seg(b, low, high)
  ensures unchanged(a, b, low, high)
  ensures multiset(a[..]) == multiset(b[..])
  decreases high - low
{
  // Handle empty segment or array
  if low >= high || a.Length == 0 {
    b := new T[a.Length];
    for i := 0 to a.Length
      invariant forall j :: 0 <= j < i ==> b[j] == a[j]
    {
      b[i] := a[i];
    }
    return;
  }

  b := new T[a.Length];

  // Copy the entire array first
  for i := 0 to a.Length
    invariant forall j :: 0 <= j < i ==> b[j] == a[j]
  {
    b[i] := a[i];
  }

  // Optimized selection sort for the segment [low, high)
  var i := low;
  while i < high - 1
    invariant low <= i <= high - 1
    invariant sorted_seg(b, low, i)
    invariant forall k, l :: low <= k < i && i <= l < high ==> b[k] <= b[l]
    invariant unchanged(a, b, low, high)
    invariant multiset(a[..]) == multiset(b[..])
    decreases high - i
  {
    // Find minimum element in unsorted part
    var minIndex := i;
    var j := i + 1;

    while j < high
      invariant i + 1 <= j <= high
      invariant forall k :: i <= k < j ==> b[minIndex] <= b[k]
      invariant minIndex >= i && minIndex < high
      decreases high - j
    {
      if b[j] < b[minIndex] {
        minIndex := j;
      }
      j := j + 1;
    }

    // Swap if necessary (optimized: only swap when minIndex != i)
    if minIndex != i {
      var temp := b[i];
      b[i] := b[minIndex];
      b[minIndex] := temp;
    }

    // Verify the invariant after swap
    assert forall k :: low <= k <= i ==> b[k] <= b[i];
    assert forall k :: i < k < high ==> b[i] <= b[k];

    i := i + 1;
  }

  // Final verification
  assert sorted_seg(b, low, high);
}

